using System.Windows;
using System.Windows.Controls;
using DomainConsole.Shared;
namespace DomainConsole;
public partial class MainWindow {
 static bool QueueOnly32(IEnumerable<string>? sources)=>sources!=null&&sources.Any()&&sources.All(s=>s.StartsWith("PendingFileRenameOperations",StringComparison.OrdinalIgnoreCase));
 static string RebootDescription32(RebootEvidence reboot){bool only=QueueOnly32(reboot.Sources);var required=only?(bool?)null:reboot.Required;var text="## Проверка перезагрузки клиента\n"+LocalDateConverter.Format(reboot.CollectedUtc)+" · "+(only?"Старый снимок содержит только общие файловые операции. Требование Windows Update не подтверждено; обновите статус.":required==true?"Перезагрузка подтверждена Windows Update / CBS. Перезагрузите в согласованное время, затем проверьте результат.":required==false?"Флаги перезагрузки Windows Update / CBS отсутствуют.":"Требование перезагрузки проверить не удалось.");if(reboot.Sources.Count>0&&!only)text+="\nИсточник: "+string.Join("; ",reboot.Sources.Select(ShortRebootSource));if(reboot.Error.Length>0)text+="\nОграничения проверки: "+reboot.Error;if(reboot.PendingFileOperations.Any(s=>!string.IsNullOrWhiteSpace(s))){text+="\nЕсть общие отложенные файловые операции. Их связь с текущим обновлением не установлена; сами по себе обслуживание не останавливают.";text+="\n\n## Технические сведения · отложенные файловые операции\n";for(int i=0;i<reboot.PendingFileOperations.Count;i+=2){text+="Источник: "+reboot.PendingFileOperations[i]+"\n";text+=(i+1<reboot.PendingFileOperations.Count&&!string.IsNullOrWhiteSpace(reboot.PendingFileOperations[i+1])?"Назначение: "+reboot.PendingFileOperations[i+1]:"Действие: удаление при перезагрузке")+"\n";}}return text;}
 void Background32_Changed(object sender,RoutedEventArgs e){if(IsLoaded&&e.OriginalSource==BackgroundGroup)Store.Write("background-expanded32.json",BackgroundGroup.IsExpanded);}
 void Palette32_Changed(){HeaderRecent31.ItemsSource=null;EventList32.ItemsSource=null;headerEventsKey32="";historyEventsKey32="";historyReset35=true;ApplyEditorMode();foreach(var r in Computers){r.Refresh();r.SetConnection(r.LinkKind,r.LinkHint);r.SetActivity(r.Working,r.WorkBusy?null:r.WorkProgress,r.RecentHint,ComputerGrid.SelectedItem==r);}RefreshOutcomes();RefreshBranches();if(ComputerGrid.SelectedItem is ComputerRow row){RefreshHeader31(row);UpdateWsusStage();}}
}
